// ── Lines and properties ───────────────────────────────────────────────────

interface Prop {
    name: string;
    params: Record<string, string>;
    value: string;
    /** Offset of the line's first character in the source. */
    at: number;
}

/**
 * Split the source into properties, joining folded lines (a line that starts
 * with a space or tab continues the previous one). Offsets point into the
 * original text so a VEVENT's own lines can be cut out again.
 */
function eachProp(text: string, visit: (p: Prop) => void): void {
    const n = text.length;
    let i = 0;
    let cur = "";
    let curAt = -1;
    while (i <= n) {
        let j = text.indexOf("\n", i);
        if (j === -1) j = n;
        const end = j > i && text.charCodeAt(j - 1) === 13 ? j - 1 : j;
        const first = text.charCodeAt(i);
        if ((first === 32 || first === 9) && curAt !== -1) {
            cur += text.slice(i + 1, end);
        } else {
            if (curAt !== -1 && cur) {
                const p = parseProp(cur, curAt);
                if (p) visit(p);
            }
            cur = text.slice(i, end);
            curAt = i;
        }
        i = j + 1;
    }
    if (curAt !== -1 && cur) {
        const p = parseProp(cur, curAt);
        if (p) visit(p);
    }
}

const NO_PARAMS: Record<string, string> = Object.freeze({}) as Record<string, string>;

function parseProp(line: string, at: number): Prop | null {
    // The name and parameters end at the first colon outside double quotes.
    // Most lines have no parameters and no quotes, so look for that first.
    const colon0 = line.indexOf(":");
    if (colon0 <= 0) return null;
    const semi0 = line.indexOf(";");
    if (semi0 === -1 || semi0 > colon0) {
        return { name: line.slice(0, colon0).trim().toUpperCase(), params: NO_PARAMS, value: line.slice(colon0 + 1), at };
    }
    let quoted = false;
    let colon = -1;
    for (let k = 0; k < line.length; k++) {
        const c = line.charCodeAt(k);
        if (c === 34) quoted = !quoted;
        else if (c === 58 && !quoted) { colon = k; break; }
    }
    if (colon <= 0) return null;
    const head = line.slice(0, colon);
    const value = line.slice(colon + 1);
    const parts: string[] = [];
    let from = 0;
    let buf = "";
    quoted = false;
    for (let k = 0; k < head.length; k++) {
        const c = head.charCodeAt(k);
        if (c === 34) { buf += head.slice(from, k); from = k + 1; quoted = !quoted; continue; }
        if (c === 59 && !quoted) { parts.push(buf + head.slice(from, k)); buf = ""; from = k + 1; }
    }
    parts.push(buf + head.slice(from));
    const name = parts[0].trim().toUpperCase();
    if (!name) return null;
    const params: Record<string, string> = {};
    for (let k = 1; k < parts.length; k++) {
        const p = parts[k];
        const eq = p.indexOf("=");
        if (eq > 0) params[p.slice(0, eq).trim().toUpperCase()] = p.slice(eq + 1);
    }
    return { name, params, value, at };
}

/** TEXT values escape newlines, commas, semicolons and backslashes. */
export function unescapeText(v: string): string {
    return v.replace(/\\([\\;,nN])/g, (_, c: string) => (c === "n" || c === "N" ? "\n" : c));
}

